INSERT INTO products (id,name,description,badge,category,price_cents,currency,image,catalog_details,active) VALUES
('AUT-01','تحليل فرص الأتمتة','مراجعة وتحليل 3 مسارات عمل يدوية في منشأتك وتصميم خريطة سير عمل مؤتمتة تلغي الهدر الزمني.','الاستشارات وهندسة العمليات','AUT',120000,'SAR','/images/products/AUT-01.jpg','{"sku":"AUT-01","nameAr":"تحليل فرص الأتمتة","nameEn":"Business Process Automation Discovery","categoryId":"AUT","subCategory":"الاستشارات وهندسة العمليات","status":"ready_to_sell","pricing":{"amount":1200,"currency":"SAR","type":"fixed","billingCycle":"one_time"},"deliveryDays":5,"revisions":{"count":1,"scope":"مراجعة مخططات سير العمل لتدقيق الاستثناءات التشغيلية"},"publicContent":{"shortDescription":"مراجعة وتحليل 3 مسارات عمل يدوية في منشأتك وتصميم خريطة سير عمل مؤتمتة تلغي الهدر الزمني.","detailedDescription":"دراسة استشارية وتشغيلية تهدف إلى تحرير فريقك من الأعمال الروتينية المتكررة. نقوم بفحص 3 عمليات يدوية تستهلك وقت موظفيك (مثل: نقل بيانات الطلبات من المتجر لجداول الشحن، إرسال إشعارات العقود للعملاء، أو فرز الفواتير والمرفقات)، ورسم مخطط تدفق رقمي تفصيلي (Workflow Diagram)، واختيار أدوات الربط الأنسب والأقل تكلفة (Make, n8n, أو سكريبتات مخصصة)، وتحديد زمن التوفير المتوقع وتكلفة التنفيذ بدقة.","targetAudience":"صاحب منشأة يعاني موظفوه من تكرار نسخ ولصق البيانات بين الأنظمة المختلفة ويضيعون ساعات يومية في أعمال روتينية.","problemSolved":"أخطاء النقل البشري المتبادلة، بطء العمليات، وارتفاع التكلفة التشغيلية لتوظيف مدخلي بيانات.","expectedOutcome":"خريطة طريق واضحة بالأدوات والتكاليف المحددة لأتمتة 3 عمليات حيوية في الشركة ووقف الهدر فوراً.","deliverables":["جلسة استماع وتشخيص (60 دقيقة)","مخططات سير العمل الرقمية (Workflow Architecture Diagrams) لـ 3 عمليات","تقرير التوصيات والأولويات (PDF)"],"exclusions":["البرمجة والتنفيذ الفعلي لمسارات الأتمتة (تتوفر عبر منتجات AUT-02 و AUT-03)"],"ctaButton":"اطلب تحليل مسارات الأتمتة","seo":{"title":"استشارات وهندسة أتمتة العمليات التجارية | ونشوت OneShot","description":"تخلص من الروتين ووفّر ساعات عمل فريقك مع خدمة تحليل وهندسة أتمتة 3 عمليات تجارية بمخططات واضحة."}},"english":{"subCategory":"Consulting & Process Engineering","shortDescription":"Audit and analyze 3 manual business workflows in your organization and design an automated workflow blueprint that eliminates wasted hours.","detailedDescription":"An operational consulting study designed to free your team from repetitive manual tasks. We inspect 3 manual processes consuming staff time (such as copying order data to shipping sheets, sending contract notifications, or sorting invoices and attachments), map detailed digital workflow architecture diagrams, select the most cost-effective automation tools (Make, n8n, or custom scripts), and calculate expected time savings and implementation costs.","deliverables":["60-minute discovery and diagnostic session","Digital workflow architecture diagrams for 3 business processes","Prioritized automation recommendations and ROI report (PDF)"],"exclusions":["Hands-on coding and live execution of automation flows (available via AUT-02 and AUT-03)"],"revisionsScope":"Review of workflow diagrams to verify operational edge cases and exceptions","ctaButton":"Request Automation Discovery"},"sourceKind":"catalog","image":"/images/products/AUT-01.jpg","sortOrder":0}'::jsonb,true),
('AUT-02','أتمتة بسيطة (Simple Flow)','بناء وربط مسار أتمتة مباشر بين تطبيقين بمشغل واحد وحتى 3 إجراءات تلقائية وسجل معالجة أخطاء.','مسارات العمل السريعة','AUT',150000,'SAR','/images/products/AUT-02.jpg','{"sku":"AUT-02","nameAr":"أتمتة بسيطة (Simple Flow)","nameEn":"Simple 2-App Workflow Automation","categoryId":"AUT","subCategory":"مسارات العمل السريعة","status":"ready_to_sell","pricing":{"amount":1500,"currency":"SAR","type":"starts_at","billingCycle":"one_time"},"deliveryDays":5,"revisions":{"count":2,"scope":"ضبط شروط الفلترة أو تعديل نص الرسالة التلقائية"},"publicContent":{"shortDescription":"بناء وربط مسار أتمتة مباشر بين تطبيقين بمشغل واحد وحتى 3 إجراءات تلقائية وسجل معالجة أخطاء.","detailedDescription":"ربط ذكي ينقل البيانات تلقائياً بين برنامجين دون أي تدخل بشري (مثل: إرسال رسالة واتساب للعميل فور تسجيل طلبه في المتجر، أو تسجيل الفاتورة في جدول إكسل فور استلام الأموال). يتضمن المسار إعداد مشغل واحد (Trigger) وما يصل إلى 3 إجراءات متتابعة (Actions)، مع تنقية البيانات، وإعداد سجل تنبيهات بالأخطاء عبر البريد أو التليجرام.","targetAudience":"متجر إلكتروني أو مشروع ناشئ يحتاج ربطاً سريعاً بين أداتين يوميتين لإلغاء النقل اليدوي للمعلومات.","problemSolved":"تأخر إرسال التنبيهات للعملاء، وسقوط بعض الطلبات سهواً بين المنصات المختلفة.","expectedOutcome":"تدفق سلس وفوري للمعلومة في أجزاء من الثانية فور حدوث الحدث الأساسي، بنسبة دقة واستقرار عالية.","deliverables":["مسار أتمتة واحد نشط ومختبر يربط تطبيقين بحد أقصى 3 إجراءات","سجل مراقبة الأخطاء","دليل تشغيل وشرح للمسار"],"exclusions":["اشتراك منصات الأتمتة (مثل Make أو Zapier إذا تجاوز الاستخدام الخطة المجانية)","بناء واجهات برمجة مخصصة غير متوفرة"],"ctaButton":"اطلب أتمتة مسار عملك"},"english":{"subCategory":"Rapid Workflow Automations","shortDescription":"Connect two digital apps in a single automated workflow (Trigger + up to 3 Actions) to move data and alerts instantly without human intervention.","detailedDescription":"Turn repetitive daily actions into an automatic background process. We connect two apps you already use (e.g., website form to Google Sheets with a Telegram/Slack alert) in a tested workflow with up to 3 sequential actions, error logging, and an operational handover guide.","deliverables":["One active, tested automation workflow connecting 2 apps (up to 3 actions)","Automated error monitoring log","Operational walkthrough and handover guide"],"exclusions":["Third-party automation platform subscription fees (Make or Zapier if usage exceeds free tiers)","Custom API development for unsupported legacy systems"],"revisionsScope":"Adjusting filter conditions or refining automated message templates","ctaButton":"Request Simple Workflow Automation"},"sourceKind":"catalog","image":"/images/products/AUT-02.jpg","sortOrder":1}'::jsonb,true),
('AUT-03','أتمتة متعددة الخطوات','أتمتة منظومة معقدة تربط حتى 3 تطبيقات وتشمل 8 خطوات بشروط تفرع منطقية ومعالجة احترافية للأخطاء.','الأتمتة المتقدمة','AUT',350000,'SAR','/images/products/AUT-03.jpg','{"sku":"AUT-03","nameAr":"أتمتة متعددة الخطوات","nameEn":"Multi-Step Advanced Workflow Automation","categoryId":"AUT","subCategory":"الأتمتة المتقدمة","status":"ready_to_sell","pricing":{"amount":3500,"currency":"SAR","type":"starts_at","billingCycle":"one_time"},"deliveryDays":10,"revisions":{"count":2,"scope":"ضبط معايير الشروط التفرعية وتنسيق البيانات المنقولة"},"publicContent":{"shortDescription":"أتمتة منظومة معقدة تربط حتى 3 تطبيقات وتشمل 8 خطوات بشروط تفرع منطقية ومعالجة احترافية للأخطاء.","detailedDescription":"بناء مسار تشغيلي آلي متقدم يعالج دورة عمل تجارية كاملة. يشمل ربط 3 تطبيقات مختلفة في سيناريو واحد متناغم يضم حتى 8 خطوات، مع استخدام الشروط المتفرعة (Routers / Branching Logic)، وتنسيق التواريخ والأرقام، وتوليد الفواتير، وتحديث المخزون وقواعد البيانات مع استعادة تلقائية عند انقطاع الاتصال.","targetAudience":"منشأة تشهد عمليات تشغيلية متشابكة تتطلب موافقات وتحديثات متزامنة في برامج الحسابات والمبيعات والمخازن.","deliverables":["سيناريو أتمتة متقدم (حتى 3 تطبيقات و8 خطوات)","شروط تفرع ذكية","نظام إعادة المحاولة الآلي عند الفشل","خريطة توثيق المسار"],"exclusions":["اشتراك المنصات الوسيطة في حال العمليات الضخمة جداً (أكثر من 10,000 عملية شهرياً)"],"ctaButton":"اطلب الأتمتة المتقدمة"},"english":{"subCategory":"Advanced Multi-System Automation","shortDescription":"Build an advanced multi-step automation scenario connecting up to 3 systems and 8 actions with conditional routing, data formatting, and error recovery.","detailedDescription":"End-to-end orchestration for complex operational workflows across up to 3 applications and 8 steps. Includes conditional branching logic, data transformation, automatic retry handling on failure, and a complete architectural map of the scenario.","deliverables":["Advanced automation scenario (up to 3 apps and 8 steps)","Smart conditional routing and branching logic","Automated retry and failure recovery handling","Complete workflow documentation map"],"exclusions":["Middleware platform subscription costs for high-volume enterprise usage (>10,000 operations/month)"],"revisionsScope":"Refining branching conditions and payload data formatting","ctaButton":"Request Advanced Automation"},"sourceKind":"catalog","image":"/images/products/AUT-03.jpg","sortOrder":2}'::jsonb,true),
('AUT-04','تنظيم العملاء المحتملين (CRM Pipeline)','أتمتة التقاط العملاء من الإعلانات والنماذج وتوجيههم لـ CRM واحد مع التصنيف الآلي ومنع التكرار.','أنظمة المبيعات وإدارة العملاء','AUT',250000,'SAR','/images/products/AUT-04.jpg','{"sku":"AUT-04","nameAr":"تنظيم العملاء المحتملين (CRM Pipeline)","nameEn":"Lead Capture, Enrichment & CRM Pipeline","categoryId":"AUT","subCategory":"أنظمة المبيعات وإدارة العملاء","status":"ready_to_sell","pricing":{"amount":2500,"currency":"SAR","type":"starts_at","billingCycle":"one_time"},"deliveryDays":7,"revisions":{"count":2,"scope":"ضبط قواعد توزيع العملاء وحقول التصنيف"},"publicContent":{"shortDescription":"أتمتة التقاط العملاء من الإعلانات والنماذج وتوجيههم لـ CRM واحد مع التصنيف الآلي ومنع التكرار.","detailedDescription":"بناء مسار التقاط العملاء المهتمين (Leads) لحظة بلحظة دون ضياع أي فرصة بيعية. نقوم بربط إعلاناتك (TikTok Lead Forms, Meta Instant Forms, أو نماذج الموقع) بنظام إدارة علاقات عملاء موحد (مثل HubSpot, Zoho, أو Notion CRM)، وتصنيف العميل تلقائياً، والتحقق من عدم تكرار رقم الهاتف، وإرسال إشعار فوري لمندوب المبيعات.","deliverables":["ربط نماذج الإعلانات بنظام CRM واحد","مسار تصنيف وفلترة ومنع التكرار","إشعار فوري لمسؤول المبيعات","تقرير تدفق البيانات"],"exclusions":["اشتراك باقة الـ CRM المدفوعة"],"ctaButton":"اطلب نظام تنظيم العملاء"},"english":{"subCategory":"Sales Systems & CRM Pipelines","shortDescription":"Automatically capture leads from ad campaigns and forms, deduplicate and enrich records, and route prospects into your CRM with instant sales alerts.","detailedDescription":"Stop losing leads in scattered spreadsheets. We connect your landing pages and lead forms directly to your CRM, apply automatic deduplication and lead scoring/tagging rules, and trigger instant WhatsApp/Slack alerts to your sales reps.","deliverables":["Integration of lead forms and ad channels with one CRM system","Automated lead tagging, filtering, and deduplication pipeline","Instant notification trigger for the assigned sales representative","Data flow verification report"],"exclusions":["Paid CRM platform seat subscriptions"],"revisionsScope":"Adjusting lead assignment rules and custom CRM classification fields","ctaButton":"Build Your CRM Lead Pipeline"},"sourceKind":"catalog","image":"/images/products/AUT-04.jpg","sortOrder":3}'::jsonb,true),
('AUT-05','أتمتة عروض الأسعار','نظام لتوليد عروض أسعار PDF رسمية واحترافية فوراً من نموذج إدخال بسيط مع خطوة اعتماد وتوجيه للعميل.','أتمتة المبيعات والوثائق','AUT',300000,'SAR','/images/products/AUT-05.jpg','{"sku":"AUT-05","nameAr":"أتمتة عروض الأسعار","nameEn":"Automated Quotation Generation System","categoryId":"AUT","subCategory":"أتمتة المبيعات والوثائق","status":"ready_to_sell","pricing":{"amount":3000,"currency":"SAR","type":"starts_at","billingCycle":"one_time"},"deliveryDays":9,"revisions":{"count":2,"scope":"تنسيق شكل ملف الـ PDF وحقول النموذج"},"publicContent":{"shortDescription":"نظام لتوليد عروض أسعار PDF رسمية واحترافية فوراً من نموذج إدخال بسيط مع خطوة اعتماد وتوجيه للعميل.","detailedDescription":"برمجة نظام مؤتمت يعتمد على نموذج إدخال سريع يملؤه مسؤول المبيعات من الجوال أو الكمبيوتر، ليقوم النظام بحساب التكاليف والضريبة وتوليد عرض سعر رسمي فاخر بصيغة PDF بهوية شركتك وأرقام مرجعية مشفرة، مع إمكانية إرسال مسودة للمدير للاعتماد، ثم إرسال العرض للعميل عبر الإيميل أو الواتساب تلقائياً.","deliverables":["نموذج إدخال بيانات متجاوب","قالب عرض سعر PDF ديناميكي مصمم بهويتك","مسار أتمتة التوليد والإرسال","سجل لحفظ عروض الأسعار"],"exclusions":["التوقيع الرقمي القانوني المشفر عبر منصات خارجية مدفوعة"],"ctaButton":"اطلب نظام أتمتة عروض الأسعار"},"english":{"subCategory":"Sales & Document Automation","shortDescription":"Generate branded PDF quotations automatically from a structured input form and deliver them to clients via email or WhatsApp in seconds.","detailedDescription":"Accelerate your sales cycle with instant, error-free proposals. Your team fills out a simple mobile-ready form, and the system automatically calculates totals, populates a branded PDF quotation template, archives the record, and dispatches it to the client.","deliverables":["Responsive data entry form for sales reps","Dynamic PDF quotation template styled with your brand identity","Automated generation and delivery workflow","Centralized log of issued quotations"],"exclusions":["Paid third-party cryptographic legal e-signature platform fees"],"revisionsScope":"Formatting PDF layout margins and form input fields","ctaButton":"Automate Your Quotations"},"sourceKind":"catalog","image":"/images/products/AUT-05.jpg","sortOrder":4}'::jsonb,true),
('AUT-06','أتمتة مستندات تجارية','توليد تلقائي للوثائق والعقود والشهادات من مصدر بيانات واحد (جداول أو CRM) لـ قالبين حتى 10 حقول لكل قالب.','الوثائق الرقمية','AUT',250000,'SAR','/images/products/AUT-06.jpg','{"sku":"AUT-06","nameAr":"أتمتة مستندات تجارية","nameEn":"Business Document Automation & Templating","categoryId":"AUT","subCategory":"الوثائق الرقمية","status":"ready_to_sell","pricing":{"amount":2500,"currency":"SAR","type":"starts_at","billingCycle":"one_time"},"deliveryDays":8,"revisions":{"count":2,"scope":"تنسيق هوامش المستند ومواقع الحقول المدمجة"},"publicContent":{"shortDescription":"توليد تلقائي للوثائق والعقود والشهادات من مصدر بيانات واحد (جداول أو CRM) لـ قالبين حتى 10 حقول لكل قالب.","detailedDescription":"تحويل البيانات المجمعة في جداولك أو أنظمتك السحابية إلى وثائق رسمية منسقة وجاهزة للطباعة أو الإرسال دون أي جهد يدوي. يشمل العمل إعداد وتصميم قالبين تجاريين ديناميكيين (مثل: عقود اتفاق، سندات استلام، أو شهادات)، وربطها بمصدر بياناتك، بحيث يتم ملء ما يصل إلى 10 حقول متغيرة تلقائياً.","deliverables":["قالبا مستندات ديناميكيان متطابقان مع الهوية","ربط الأتمتة بمصدر بيانات واحد","استخراج حتى 10 حقول لكل قالب","اختبار توليد 20 مستنداً"],"exclusions":["الصياغة القانونية لبنود العقود"],"ctaButton":"اطلب أتمتة مستنداتك التجارية"},"english":{"subCategory":"Digital Document Workflows","shortDescription":"Automate the creation of contracts, certificates, or operational letters by merging live database rows into 2 branded document templates.","detailedDescription":"Eliminate manual copy-pasting into Word files. We design two dynamic document templates matched to your brand, connect them to your data source, map up to 10 merge fields per template, and validate batch generation across 20 test documents.","deliverables":["2 dynamic document templates aligned with your brand identity","Automation connection to one structured data source","Mapping of up to 10 dynamic fields per template","Live test run generating 20 verified documents"],"exclusions":["Legal drafting or counsel review of contract clauses"],"revisionsScope":"Adjusting document margins and merged field placement","ctaButton":"Automate Business Documents"},"sourceKind":"catalog","image":"/images/products/AUT-06.jpg","sortOrder":5}'::jsonb,true),
('AUT-07','لوحة مؤشرات أعمال (Dashboard)','لوحة تحكم تفاعلية تربط مصدر بياناتك المباشر بـ 8 مؤشرات أداء ورسوم بيانية لقرارات تجارية حاسمة.','ذكاء الأعمال والتقارير','AUT',350000,'SAR','/images/products/AUT-07.jpg','{"sku":"AUT-07","nameAr":"لوحة مؤشرات أعمال (Dashboard)","nameEn":"Live Interactive Business Dashboard","categoryId":"AUT","subCategory":"ذكاء الأعمال والتقارير","status":"ready_to_sell","pricing":{"amount":3500,"currency":"SAR","type":"starts_at","billingCycle":"one_time"},"deliveryDays":10,"revisions":{"count":2,"scope":"ضبط أنواع الرسوم البيانية وتوزيع البطاقات"},"publicContent":{"shortDescription":"لوحة تحكم تفاعلية تربط مصدر بياناتك المباشر بـ 8 مؤشرات أداء ورسوم بيانية لقرارات تجارية حاسمة.","detailedDescription":"تجميع أرقام وإحصائيات عملك المشتتة في لوحة تحكم بصرية واحدة ومباشرة (Business Intelligence Dashboard عبر Looker Studio أو Power BI أو واجهة مخصصة). نقوم بربط مصدر بياناتك، وبناء 8 مؤشرات أداء رئيسية (KPIs)، مع مرشحات ذكية تتيح لك تصفية البيانات حسب التاريخ أو الفرع بنقرة زر.","deliverables":["لوحة مؤشرات تفاعلية سحابية تضم 8 مؤشرات ورسوم بيانية","فلاتر زمنية وتصنيفية","ربط مصدر بيانات واحد","رابط وصول آمن للمدير"],"exclusions":["تنقية البيانات التاريخية غير المنظمة","اشتراكات برامج BI المدفوعة إن رغب العميل"],"ctaButton":"اطلب لوحة مؤشرات أعمالك"},"english":{"subCategory":"Business Intelligence & Reporting","shortDescription":"A live, interactive cloud dashboard displaying 8 core KPIs and visual charts connected directly to your operational or sales data source.","detailedDescription":"Replace static weekly spreadsheets with real-time executive visibility. We connect your primary data source to an interactive cloud dashboard featuring 8 key performance indicators, date and category filters, and secure manager access.","deliverables":["Interactive cloud dashboard featuring 8 KPIs and visual charts","Dynamic date-range and category filters","Live connection to one primary data source","Secure access link for management"],"exclusions":["Manual cleaning of unstructured historical legacy data","Paid third-party BI tool licenses if selected by the client"],"revisionsScope":"Refining chart types and KPI card arrangement","ctaButton":"Request Live Business Dashboard"},"sourceKind":"catalog","image":"/images/products/AUT-07.jpg","sortOrder":6}'::jsonb,true),
('AUT-08','لوحة إدارة مخصصة (Custom Admin Portal)','تطوير لوحة تحكم ويب داخلية متكاملة حتى 3 وحدات تشغيلية ودورين للمستخدمين مع صلاحيات وتصدير بيانات.','الأنظمة المخصصة ولوحات التحكم','AUT',800000,'SAR','/images/products/AUT-08.jpg','{"sku":"AUT-08","nameAr":"لوحة إدارة مخصصة (Custom Admin Portal)","nameEn":"Custom Web-Based Operations Portal","categoryId":"AUT","subCategory":"الأنظمة المخصصة ولوحات التحكم","status":"ready_to_sell","pricing":{"amount":8000,"currency":"SAR","type":"starts_at","billingCycle":"one_time"},"deliveryDays":20,"revisions":{"count":2,"scope":"ضبط حقول الجداول وشاشات الإدخال"},"publicContent":{"shortDescription":"تطوير لوحة تحكم ويب داخلية متكاملة حتى 3 وحدات تشغيلية ودورين للمستخدمين مع صلاحيات وتصدير بيانات.","detailedDescription":"بناء نظام برمجي داخلي مخصص يدير عمليات مشروعك بالطريقة التي تناسب آلية عملك. يشمل النظام تطوير حتى 3 وحدات تشغيلية (مثل: وحدة إدارة العملاء والطلبات، وحدة متابعة المهام والتشغيل، ووحدة إدارة الفواتير والمقبوضات)، مع واجهة عربية سريعة بهوية شركتك، ونظام صلاحيات يفرق بين دورين، وخاصية تصدير البيانات إلى Excel/PDF.","deliverables":["تطبيق ويب كامل للوحة الإدارة","3 وحدات تشغيلية","دورين للمستخدمين مع نظام صلاحيات","ميزة تصدير Excel","كود المصدر وقاعدة البيانات"],"exclusions":["تكلفة الخادم السحابي وقاعدة البيانات","تطبيقات جوال أصلية"],"ctaButton":"اطلب لوحة إدارتك المخصصة"},"english":{"subCategory":"Custom Systems & Control Panels","shortDescription":"A custom web-based internal operations portal with 3 functional modules, role-based access control, database storage, and Excel exports.","detailedDescription":"A tailored web application built for your internal operations team. Includes 3 core operational modules (such as orders, inventory, or task tracking), two user permission roles, searchable data tables with Excel export, and full source code delivery.","deliverables":["Full web administration portal application","3 custom operational modules","2 user roles with role-based access control","One-click Excel data export feature","Complete source code and database schema"],"exclusions":["Ongoing cloud server and database hosting fees","Native iOS/Android mobile store applications"],"revisionsScope":"Adjusting table columns and data entry screen fields","ctaButton":"Build Custom Operations Portal"},"sourceKind":"catalog","image":"/images/products/AUT-08.jpg","sortOrder":7}'::jsonb,true),
('AUT-09','تكامل API (API Integration)','ربط برمجي مباشر بين نظامين مختلفين عبر الـ API لتنفيذ حتى 3 عمليات متزامنة مع توثيق وسجلات وفشل آمن.','الربط البرمجي المباشر','AUT',300000,'SAR','/images/products/AUT-09.jpg','{"sku":"AUT-09","nameAr":"تكامل API (API Integration)","nameEn":"Custom REST API Integration & Webhooks","categoryId":"AUT","subCategory":"الربط البرمجي المباشر","status":"ready_to_sell","pricing":{"amount":3000,"currency":"SAR","type":"starts_at","billingCycle":"one_time"},"deliveryDays":10,"revisions":{"count":2,"scope":"ضبط حقول البيانات ومعدل تكرار المزامنة"},"publicContent":{"shortDescription":"ربط برمجي مباشر بين نظامين مختلفين عبر الـ API لتنفيذ حتى 3 عمليات متزامنة مع توثيق وسجلات وفشل آمن.","detailedDescription":"الربط التقني العميق على مستوى الخوادم بين نظامين أو منصتين لتبادل البيانات فورياً دون وسائط بطيئة. يشمل العمل قراءة مستندات الـ API للنظامين، كتابة وتطوير الأكواد البرمجية للربط (Endpoints & Webhooks)، تنفيذ حتى 3 عمليات رئيسية مع معمارية أمان تضمن سرية التوكنز، وبناء سجلات تدقيق، ونظام فشل آمن.","deliverables":["ربط برمجي مستقر لنظامين ينفذ 3 عمليات معتمدة","نظام مراقبة وسجلات Webhook","ملف توثيق تقني للـ API (API Docs)"],"exclusions":["تعديل الأكواد البرمجية للأنظمة القديمة من طرف العميل"],"ctaButton":"اطلب تكامل الـ API المباشر"},"english":{"subCategory":"Direct API Engineering","shortDescription":"Custom REST API and Webhook integration synchronizing 3 core operations between two software platforms with full logging and technical documentation.","detailedDescription":"When off-the-shelf connectors fall short, we engineer a reliable custom API bridge between two systems. Supports 3 core data synchronization operations, webhook signature validation, error monitoring logs, and concise API documentation.","deliverables":["Stable programmatic integration between 2 systems executing 3 core operations","Webhook monitoring and error logging setup","Technical API integration documentation (API Docs)"],"exclusions":["Refactoring legacy source code inside third-party client systems"],"revisionsScope":"Adjusting mapped payload fields and sync frequency","ctaButton":"Request Custom API Integration"},"sourceKind":"catalog","image":"/images/products/AUT-09.jpg","sortOrder":8}'::jsonb,true),
('AUT-10','ربط بوابة دفع (Payment Gateway Integration)','ربط وتكامل فني لبوابة دفع إلكتروني معتمدة واحدة عبر صفحة دفع مستضافة مع تحقق خادمي آمن لحالة الطلب.','بوابات الدفع الإلكتروني','AUT',300000,'SAR','/images/products/AUT-10.jpg','{"sku":"AUT-10","nameAr":"ربط بوابة دفع (Payment Gateway Integration)","nameEn":"Live Payment Gateway API Integration","categoryId":"AUT","subCategory":"بوابات الدفع الإلكتروني","status":"ready_to_sell","pricing":{"amount":3000,"currency":"SAR","type":"starts_at","billingCycle":"one_time"},"deliveryDays":10,"revisions":{"count":2,"scope":"ضبط صفحات إعادة التوجيه وتنسيق رسائل الرد"},"publicContent":{"shortDescription":"ربط وتكامل فني لبوابة دفع إلكتروني معتمدة واحدة عبر صفحة دفع مستضافة مع تحقق خادمي آمن لحالة الطلب.","detailedDescription":"التأسيس والربط البرمجي الاحترافي لبوابة دفع إلكتروني واحدة على موقعك أو تطبيقك (مثل: Network International N-Genius KSA، PayTabs، Payzaty، Noon Payments، أو PayOne). يشمل العمل برمجة نقطة التحقق من التوكن، توجيه العميل إلى صفحة الدفع المستضافة الآمنة، استقبال والتحقق الخادمي الآمن من إشعارات الدفع (Server-Side Webhook Verification & HMAC Signature)، وحجب وعزل أرقام البطاقات المصرفية بنظام PCI-DSS Sanitized.","deliverables":["ربط بوابة دفع واحدة بنمط Live","صفحة دفع مستضافة","تحقق خادمي من الـ Webhook وتوقيعه الرقمي","تسجيل عمليات الدفع في لوحة التحكم","اختبار عملي لمدفوعات حقيقية"],"exclusions":["فتح الحساب البنكي أو الحصول على موافقة مزود البوابة","تحصيل أموال المبيعات"],"ctaButton":"اطلب ربط بوابة الدفع"},"english":{"subCategory":"Electronic Payment Gateways","shortDescription":"End-to-end live integration of one payment gateway (PayTabs, Telr, Tap, or N-Genius) with server-side webhook verification and dashboard logging.","detailedDescription":"Accept online payments safely and reliably. We integrate one approved payment gateway in live mode, configure hosted checkout redirects, enforce cryptographic server-side webhook verification, log payment statuses in your dashboard, and verify end-to-end settlement.","deliverables":["Live integration of one electronic payment gateway","Hosted checkout page configuration","Server-side webhook and cryptographic signature verification","Payment transaction status logging in your control panel","Verified live payment test run"],"exclusions":["Opening commercial bank accounts or obtaining KYC approval from the gateway provider","Acting as a payment aggregator or holding merchant funds"],"revisionsScope":"Refining redirect return pages and payment status messages","ctaButton":"Integrate Payment Gateway"},"sourceKind":"catalog","image":"/images/products/AUT-10.jpg","sortOrder":9}'::jsonb,true),
('AUT-11','بوابة عملاء (Client Portal)','بوابة ويب تفاعلية مخصصة لعملائك تتيح تسجيل الدخول، متابعة الطلبات، تحميل الملفات، وحالة الحساب دون فوترة معقدة.','بوابات الخدمة الذاتية','AUT',750000,'SAR','/images/products/AUT-11.jpg','{"sku":"AUT-11","nameAr":"بوابة عملاء (Client Portal)","nameEn":"Self-Service Client Portal","categoryId":"AUT","subCategory":"بوابات الخدمة الذاتية","status":"ready_to_sell","pricing":{"amount":7500,"currency":"SAR","type":"starts_at","billingCycle":"one_time"},"deliveryDays":20,"revisions":{"count":2,"scope":"تنسيق شاشات البوابة وتوزيع الحقول"},"publicContent":{"shortDescription":"بوابة ويب تفاعلية مخصصة لعملائك تتيح تسجيل الدخول، متابعة الطلبات، تحميل الملفات، وحالة الحساب دون فوترة معقدة.","detailedDescription":"توفير تجربة خدمة ذاتية راقية لعملائك تغنيك عن إرسال التحديثات والملفات بالبريد والواتساب يدوياً. تشمل البوابة واجهة دخول برقم الجوال أو البريد بكلمة مرور مشفرة، لوحة متابعة للعميل يستعرض فيها طلباته النشطة وتاريخ معاملاته، مستودعاً لتحميل الملفات والعقود والفواتير الخاصة به، ونظاماً لاستقبال طلبات التعديل أو الاستفسارات.","deliverables":["تطبيق ويب لبوابة العملاء بهويتك","نظام تسجيل دخول وتوثيق","لوحة استعراض الطلبات والملفات","لوحة إدارية لفريقك لرفع التحديثات"],"exclusions":["نظام الفوترة والاشتراكات المتكررة التلقائية المعقدة","بوابات التداول المالي"],"ctaButton":"اطلب بوابة عملائك الخاصة"},"english":{"subCategory":"Self-Service Portals","shortDescription":"A branded self-service client portal with secure login, order and milestone tracking, document downloads, and revision request submission.","detailedDescription":"Elevate your client experience with a dedicated self-service web portal under your brand. Clients can sign in securely, track active orders and transaction history, download contracts and invoices, and submit inquiries, while your team manages updates from an admin view.","deliverables":["Branded client portal web application","Secure authentication and login system","Client dashboard for order tracking and file downloads","Internal staff admin view for publishing updates"],"exclusions":["Complex automated recurring billing engines","Financial trading or brokerage features"],"revisionsScope":"Adjusting portal screen layouts and field arrangement","ctaButton":"Request Client Portal"},"sourceKind":"catalog","image":"/images/products/AUT-11.jpg","sortOrder":10}'::jsonb,true),
('AUT-12','نموذج أولي لمنتج رقمي (MVP)','بناء وتطوير نموذج أولي عملي لمنتجك الرقمي يغطي رحلة مستخدم رئيسية واحدة وحتى 5 شاشات تفاعلية قابلة للاختبار.','تطوير المنتجات الرقمية (SaaS & Apps)','AUT',900000,'SAR','/images/products/AUT-12.jpg','{"sku":"AUT-12","nameAr":"نموذج أولي لمنتج رقمي (MVP)","nameEn":"Functional Digital MVP Prototype","categoryId":"AUT","subCategory":"تطوير المنتجات الرقمية (SaaS & Apps)","status":"ready_to_sell","pricing":{"amount":9000,"currency":"SAR","type":"starts_at","billingCycle":"one_time"},"deliveryDays":20,"revisions":{"count":2,"scope":"ضبط تدفق الرحلة والتفاعل البصري للشاشات"},"publicContent":{"shortDescription":"بناء وتطوير نموذج أولي عملي لمنتجك الرقمي يغطي رحلة مستخدم رئيسية واحدة وحتى 5 شاشات تفاعلية قابلة للاختبار.","detailedDescription":"تحويل فكرتك الريادية المبتكرة من مجرد رسومات نظرية إلى منتج رقمي واقعي شغال وملموس (Minimum Viable Product). نركز على القيمة الجوهرية للفكرة عبر بناء رحلة مستخدم أساسية واحدة تتضمن حتى 5 شاشات تفاعلية مبرمجة ومربوطة بقاعدة بيانات حقيقية، تمكنك من اختبار فكرتك مع المستخدمين الأوائل في السوق، وعرض نموذج شغال ومقنع أمام المستثمرين.","deliverables":["تطبيق ويب تفاعلي شغال منشور على خادم تجريبي","5 شاشات وظيفية","قاعدة بيانات مصغرة","تسليم الكود المصدري وتقرير فحص الأداء"],"exclusions":["تطوير ميزات جانبية معقدة خارج الرحلة الجوهرية","نشر التطبيق في متجري App Store و Google Play (يُبنى كـ Web App سريع)"],"ctaButton":"اطلب بناء نموذجك الأولي MVP"},"english":{"subCategory":"Digital Product Development (SaaS & Apps)","shortDescription":"Turn your digital product idea into a functional, deployed web MVP featuring up to 5 core screens, user authentication, and a live database.","detailedDescription":"Validate your startup or internal product idea with real users in weeks instead of months. We design and engineer a working web MVP with up to 5 core functional screens, database persistence, and cloud staging deployment, complete with source code handover.","deliverables":["Functional interactive web application deployed on a staging server","Up to 5 core functional screens","Structured operational database","Full source code handover and performance check report"],"exclusions":["Secondary features outside the core MVP user journey","Native App Store / Google Play submission (built as a responsive Web App)"],"revisionsScope":"Refining core user journey flow and screen interactions","ctaButton":"Launch Your MVP Prototype"},"sourceKind":"catalog","image":"/images/products/AUT-12.jpg","sortOrder":11}'::jsonb,true),
('DIG-01','قالب فاتورة وعرض سعر','قالبا فواتير وعروض أسعار رسميان ومخصصان بهوية شركتك قابلان للتعديل بالكامل على Word و Excel.','القوالب المكتبية','DIG',70000,'SAR','/images/products/DIG-01.jpg','{"sku":"DIG-01","nameAr":"قالب فاتورة وعرض سعر","nameEn":"Branded Invoice & Quotation Templates","categoryId":"DIG","subCategory":"القوالب المكتبية","status":"ready_to_sell","pricing":{"amount":700,"currency":"SAR","type":"fixed","billingCycle":"one_time"},"deliveryDays":4,"revisions":{"count":2,"scope":"توزيع الجداول وتنسيق الخطوط"},"publicContent":{"shortDescription":"قالبا فواتير وعروض أسعار رسميان ومخصصان بهوية شركتك قابلان للتعديل بالكامل على Word و Excel.","detailedDescription":"تصميم وإعداد ملفين رقميين فاخرين لإصدار فواتيرك وعروض أسعارك اليومية بأناقة تعكس هيبة علامتك. يشمل العمل قالب Excel مبرمجاً بمعادلات حساب المجموع وضريبة القيمة المضافة 15% تلقائياً، وقالب Word منسقاً للطباعة وتصدير الـ PDF، مع تضمين بياناتك الرسمية (السجل، الرقم الضريبي، الآيبان البنكي، وشروط الدفع).","deliverables":["قالب فاتورة رسمي","قالب عرض سعر رسمي (بصيغتي Word و Excel مفتوحة المصدر وقابلة للتعديل مدى الحياة)"],"exclusions":["الربط مع هيئة الزكاة والضريبة والجمارك \"زاتكا\" للفوترة الإلكترونية المشفرة"],"ctaButton":"اطلب قوالب الفواتير والأسعار"},"english":{"subCategory":"Office & Finance Templates","shortDescription":"Official, editable invoice and quotation templates in Word and Excel formats tailored to your brand colors, logo, and automatic tax calculations.","detailedDescription":"Issue polished commercial documents that reflect your brand credibility. We customize an official invoice template and quotation template with your logo, typography, and color palette in open Word and Excel formats with built-in VAT and total formulas.","deliverables":["Official branded invoice template","Official branded quotation template (editable Word & Excel formats for lifetime use)"],"exclusions":["Direct cryptographic API integration with ZATCA e-invoicing portals"],"revisionsScope":"Adjusting table layout and typography alignment","ctaButton":"Order Branded Templates"},"sourceKind":"catalog","image":"/images/products/DIG-01.jpg","sortOrder":12}'::jsonb,true),
('DIG-02','دليل PDF تفاعلي (Interactive PDF)','تصميم وإخراج دليل أو كتيب رقمي تفاعلي حتى 15 صفحة مع فهرس قابل للنقر وروابط خارجية وأناقة عربية.','النشر والكتب الرقمية','DIG',120000,'SAR','/images/products/DIG-02.jpg','{"sku":"DIG-02","nameAr":"دليل PDF تفاعلي (Interactive PDF)","nameEn":"Interactive Digital PDF Guide & E-Book","categoryId":"DIG","subCategory":"النشر والكتب الرقمية","status":"ready_to_sell","pricing":{"amount":1200,"currency":"SAR","type":"fixed","billingCycle":"one_time"},"deliveryDays":6,"revisions":{"count":2,"scope":"تنسيق كتل النصوص والخطوط والصور"},"publicContent":{"shortDescription":"تصميم وإخراج دليل أو كتيب رقمي تفاعلي حتى 15 صفحة مع فهرس قابل للنقر وروابط خارجية وأناقة عربية.","detailedDescription":"تحويل محتواك التدريبي، دليلك الإرشادي، أو كتيبك التعريفي إلى وثيقة رقمية تفاعلية ممتعة للقراءة عبر شاشات الأجهزة الذكية والكمبيوتر. يشمل العمل تنسيق وإخراج حتى 15 صفحة بتصميم عربي راقٍ، مع بناء فهرس تفاعلي ينقلك للصفحة المطلوبة بنقرة واحدة، وتفعيل الروابط الخارجية للفيديوهات والمواقع.","deliverables":["كتاب/دليل رقمي تفاعلي كامل حتى 15 صفحة","فهرس وروابط نشطة","نسخة خفيفة الوزن للمشاركة عبر الواتساب","غلاف كتاب رقمي ثلاثي الأبعاد (3D Mockup)"],"exclusions":["تأليف وكتابة محتوى الدليل من الصفر"],"ctaButton":"اطلب تصميم دليلك التفاعلي"},"english":{"subCategory":"Digital Publishing & E-Books","shortDescription":"Design and layout of an interactive digital PDF guide or e-book up to 15 pages with clickable navigation, WhatsApp-optimized size, and a 3D cover mockup.","detailedDescription":"Transform your educational content, company profile, or service guide into an engaging digital publication up to 15 pages. Includes custom editorial layout, clickable table of contents and links, a compressed version for instant WhatsApp sharing, and a 3D book mockup.","deliverables":["Interactive digital PDF guide/e-book up to 15 pages","Clickable table of contents and active hyperlinks","Lightweight version optimized for WhatsApp sharing","3D digital cover mockup"