('DIG-12','حزمة انطلاقة المستقل (Freelancer Launch Kit)','حزمة رقمية تضم 5 قوالب أساسية للمستقلين تشمل: عروض الأسعار، نماذج التواصل، عقود العمل، ومحاضر التسليم.','تمكين العمل الحر','DIG',24900,'SAR','/images/products/DIG-12.jpg','{"sku":"DIG-12","nameAr":"حزمة انطلاقة المستقل (Freelancer Launch Kit)","nameEn":"Freelancer Commercial Starter Kit","categoryId":"DIG","subCategory":"تمكين العمل الحر","status":"needs_creation_and_testing","pricing":{"amount":249,"currency":"SAR","type":"fixed","billingCycle":"one_time"},"deliveryDays":0,"revisions":{"count":0,"scope":"منتج رقمي عام يباع كما هو"},"publicContent":{"shortDescription":"حزمة رقمية تضم 5 قوالب أساسية للمستقلين تشمل: عروض الأسعار، نماذج التواصل، عقود العمل، ومحاضر التسليم.","detailedDescription":"الصندوق السحري لكل مستقل ومقدم خدمات حرة يسعى للتعامل بمهنية عالية مع عملائه. تتضمن الحزمة 5 قوالب عملية منسقة: 1. قالب عرض سعر مالي ومهني جذاب، 2. نموذج عقد عمل حر لحفظ الحقوق والشروط، 3. قوالب رسائل تواصل احترافية مع العملاء، 4. نموذج استلام المتطلبات (Brief)، و 5. نموذج محضر التسليم وطلب التقييم.","deliverables":["5 قوالب مستندات رقمية بصيغتي Word و Google Docs قابلة للتعديل","دليل إرشادي لكيفية تسعير خدماتك وإدارة العميل"],"exclusions":["التخصيص اليدوي باسم المستقل أو علامته"],"ctaButton":"احصل على حزمة المستقل الآن"},"internalReadiness":{"proposalBasis":"expansion_proposal","readinessStatus":"needs_creation_and_testing","launchRequirements":"تجهيز القوالب الخمسة وتنسيق الدليل التسعيري الملحق","estimatedEffortHours":10},"english":{"subCategory":"Freelancer Enablement","shortDescription":"A 5-template commercial starter kit for freelancers covering quotations, client onboarding briefs, service contracts, and delivery sign-offs (under creation & testing).","detailedDescription":"The essential commercial toolkit for independent consultants and freelancers to manage clients professionally. Includes 5 editable Word and Google Docs templates: financial proposal, freelance service agreement, client communication scripts, creative brief questionnaire, and final delivery sign-off form. Currently under creation and testing.","deliverables":["5 editable digital document templates in Word & Google Docs formats","Practical guide on pricing freelance services and managing client expectations"],"exclusions":["Manual branding customization with an individual freelancer logo"],"revisionsScope":"Standard digital product sold as-is","ctaButton":"Notify Me / Inquire About Kit"},"sourceKind":"catalog","image":"/images/products/DIG-12.jpg","sortOrder":23}'::jsonb,true),
