('AI-08','إعداد AI محلي (Local LLM)','تثبيت وتشغيل نموذج ذكاء اصطناعي على أجهزة شركتك يعمل بدون إنترنت وبخصوصية تامة 100% مع واجهة دردشة.','الخصوصية والأنظمة المعزولة','AI',150000,'SAR','/images/products/AI-08.jpg','{"sku":"AI-08","nameAr":"إعداد AI محلي (Local LLM)","nameEn":"Private On-Premise Local LLM Setup","categoryId":"AI","subCategory":"الخصوصية والأنظمة المعزولة","status":"ready_to_sell","pricing":{"amount":1500,"currency":"SAR","type":"starts_at","billingCycle":"one_time"},"deliveryDays":4,"revisions":{"count":1,"scope":"فحص توافق عتاد الكمبيوتر وسرعة التوليد"},"publicContent":{"shortDescription":"تثبيت وتشغيل نموذج ذكاء اصطناعي على أجهزة شركتك يعمل بدون إنترنت وبخصوصية تامة 100% مع واجهة دردشة.","detailedDescription":"إعداد وتهيئة بيئة ذكاء اصطناعي محلية معزولة بالكامل على خوادم أو أجهزة شركتك الداخلية لضمان عدم مغادرة أي بيانات حساسة خارج شبكتك. نقوم بتثبيت المحرك المحلي، اختيار أفضل نموذج لغوي متوافق مع عتادك، وربطه بواجهة محادثة سهلة الاستخدام.","deliverables":["تثبيت وضبط بيئة Ollama / LM Studio","تشغيل نموذج عربي متميز محلياً","واجهة مستخدم ويب محلية سريعة"],"exclusions":["توفير أجهزة العتاد والكمبيوتر (يجب توفر جهاز بمواصفات كافية)"],"ctaButton":"اطلب إعداد AI المحلي"},"english":{"subCategory":"Privacy & Air-Gapped AI Systems","shortDescription":"On-premise installation of a local open-weight LLM running 100% offline on your company hardware for maximum data privacy, complete with a local web chat UI.","detailedDescription":"Keep sensitive corporate data strictly inside your local network. We configure an offline local LLM environment (Ollama / LM Studio) on your company workstation or server, optimize an Arabic-capable model for your hardware specs, and connect a fast local web chat interface with zero external cloud telemetry.","deliverables":["Installation and tuning of Ollama / LM Studio local runtime","Deployment of a high-performing Arabic-capable local LLM","Fast local web chat user interface"],"exclusions":["Provisioning physical server or GPU workstation hardware (client must have compatible hardware)"],"revisionsScope":"Verifying hardware compatibility and token generation speed","ctaButton":"Request Local LLM Setup"},"sourceKind":"catalog","image":"/images/products/AI-08.jpg","sortOrder":41}'::jsonb,true),
('AI-18','تقييم جودة مساعد (Quality & Hallucination Audit)','اختبار وفحص وتدقيق 50 حالة استعلام لنظام الذكاء الاصطناعي للتأكد من انعدام الهلوسة ودقة الردود.','الفحص والتدقيق وضمان الجودة','AI',200000,'SAR','/images/products/AI-18.jpg','{"sku":"AI-18","nameAr":"تقييم جودة مساعد (Quality & Hallucination Audit)","nameEn":"AI Bot Evaluation & Hallucination Audit","categoryId":"AI","subCategory":"الفحص والتدقيق وضمان الجودة","status":"ready_to_sell","pricing":{"amount":2000,"currency":"SAR","type":"fixed","billingCycle":"one_time"},"deliveryDays":7,"revisions":{"count":1,"scope":"تدقيق وثيقة التقييم والتوصيات"},"publicContent":{"shortDescription":"اختبار وفحص وتدقيق 50 حالة استعلام لنظام الذكاء الاصطناعي للتأكد من انعدام الهلوسة ودقة الردود.","detailedDescription":"خدمة فحص وتدقيق منهجي لقياس جودة وموثوقية مساعد الذكاء الاصطناعي أو الشات بوت الخاص بك قبل أو بعد الإطلاق. نختبر النظام عبر 50 سيناريو واقعي وحرج لكشف حالات الهلوسة أو الخروج عن النص، ونسلمك تقريراً تفصيلياً مع تحسينات مباشرة لتعليمات النظام (System Prompts).","deliverables":["فحص 50 سيناريو استعلام واستفزاز للنظام","تقرير تقييم دقة الردود ونقاط الضعف","حزمة تحسينات وتعديل برومبت الحماية"],"exclusions":["إعادة برمجة النظام من الصفر إذا كان تالفاً"],"ctaButton":"اطلب فحص جودة المساعد"},"english":{"subCategory":"AI QA & Hallucination Auditing","shortDescription":"Systematic quality, safety, and hallucination audit of your existing AI bot across 50 adversarial and real-world test queries with prompt hardening fixes.","detailedDescription":"Ensure your customer-facing or internal AI assistant never fabricates policies or leaks instructions. We benchmark your bot across 50 structured edge-case and adversarial scenarios, score factual accuracy, identify hallucination triggers, and deliver hardened system prompt upgrades.","deliverables":["50-scenario factual accuracy and adversarial stress test","Detailed audit report scoring response accuracy and vulnerabilities","Hardened system prompt and guardrail upgrade package"],"exclusions":["Rebuilding a broken software architecture from scratch"],"revisionsScope":"Reviewing the evaluation audit report and guardrail recommendations","ctaButton":"Order AI Quality Audit"},"sourceKind":"catalog","image":"/images/products/AI-18.jpg","sortOrder":42}'::jsonb,true),
